import pty, os, subprocess, time, select, struct, fcntl, termios

def run_pty(command, inputs, width=80, height=24, timeout=4, env_extra=None, cwd="/tmp"):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", height, width, 0, 0))
    env = {**os.environ, "TERM":"xterm-256color"}
    if env_extra:
        env.update(env_extra)
    p = subprocess.Popen(command, stdin=slave, stdout=slave, stderr=slave, close_fds=True, preexec_fn=os.setsid, env=env, cwd=cwd)
    os.close(slave)
    os.set_blocking(master, False)
    output = b""
    start = time.time()
    inputs = sorted(inputs)
    idx = 0
    while True:
        now = time.time()
        while idx < len(inputs) and now - start >= inputs[idx][0]:
            _, data = inputs[idx]
            try:
                os.write(master, data)
            except OSError as e:
                pass
            idx += 1
        try:
            r,_,_ = select.select([master], [], [], 0.05)
            if r:
                try:
                    d = os.read(master, 65536)
                    if d:
                        output += d
                except OSError:
                    pass
        except: pass
        if p.poll() is not None:
            time.sleep(0.3)
            try:
                while True:
                    r,_,_ = select.select([master], [], [], 0.1)
                    if not r: break
                    d = os.read(master, 65536)
                    if not d: break
                    output += d
            except: pass
            break
        if now - start > timeout:
            try: p.terminate()
            except: pass
            time.sleep(0.2)
            try: p.kill()
            except: pass
            break
    os.close(master)
    try: p.wait(timeout=2)
    except: pass
    return p.returncode, output

def show(out, limit=12000):
    # printable with escapes shown
    print(repr(out[:limit]))
    if len(out) > limit:
        print(f"... total {len(out)} bytes")

def decode_visible(out):
    # strip? just print raw for human
    try:
