import sys
sys.path.insert(0,'/tmp')
from ptyhelper import run_pty
import re

def get_colors(content, fname, w=80, h=30):
    open(fname,"w").write(content)
    rc,out = run_pty(["/workspace/executable",fname], [(0.4,b"\x11")], width=w, height=h, timeout=3, cwd="/tmp")
    data=out.decode('utf-8',errors='replace')
    first_status = data.find('\x1b[7m')
    chunk = data[:first_status] if first_status!=-1 else data
    renders={}
    for m in re.finditer(r'\x1b\[(\d+)H(.*?)\x1b\[K', chunk):
        ln=int(m.group(1))
        if ln not in renders:
            renders[ln]=m.group(2)
    return renders, data

def word_color(word, ext):
    fname=f"/tmp/w{ext}"
    # put word alone on line 1, ensure no other highlighting context
    renders,_=get_colors(word+"\n", fname, w=80, h=10)
    r=renders.get(1,"")
    # find color for word: should be \x1b[38;5;NNNmWord
    m=re.search(r'\x1b\[38;5;(\d+)m'+re.escape(word)+r'\x1b', r)
    if m:
        return m.group(1)
    # check if word appears plain (no color prefix) - return None
    if word in r:
        # check if preceded by color? if word is plain, it will be just word without color code
        # But need to distinguish: e.g., r = 'word\x1b[39...' means plain
        return None
    else:
        return "NOTFOUND:"+repr(r)

# Test quickly
if __name__=="__main__":
    import sys
    ext=sys.argv[1] if len(sys.argv)>1 else ".rs"
    words=sys.argv[2:] if len(sys.argv)>2 else ["fn","let","foo"]
    for w in words:
        print(f"{w!r} -> {word_color(w, ext)!r}")
