import unicodedata

def width_py(cp):
    if cp==0x09:  # tab
        return None
    c=chr(cp)
    try:
        cat=unicodedata.category(c)
    except:
        return 1
    if cp==0x00:
        return 0
    if cat in ('Mn','Me'):
        return 0
    if cat=='Cf':
        return 1 if cp==0x00AD else 0
    if cat=='Cc':
        return 0
    # For Zl, Zp, Zs, etc., use EAW
    try:
        eaw=unicodedata.east_asian_width(c)
    except:
        return 1
    if eaw in ('W','F','A'):
        return 2
    else:
        return 1

# Generate ranges for 0x00-0x10FFFF, compress consecutive same width (excluding tab None)
ranges=[]
start=0
prev=width_py(0)
for cp in range(1, 0x110000):
    w=width_py(cp)
    if w!=prev:
        ranges.append((start, cp-1, prev))
        start=cp
        prev=w
