                if help_seen {
                    return Err("Option 'help' given more than once. Please see --help for more details".to_string());
                }
                help_seen = true;
                show_help = true;
            } else {
                return Err(format!("Unrecognized option: '{}'. Please see --help for more details", name));
            }
        } else {
            // short options: each char after -
            let chars: Vec<char> = arg[1..].chars().collect();
            for ch in chars {
                if ch == 'v' {
                    if version_seen {
                        return Err("Option 'version' given more than once. Please see --help for more details".to_string());
                    }
                    version_seen = true;
                    show_version = true;
