// Keyword lookup per filetype: returns Hl or Normal
fn keyword_hl(word: &str, ft: FileType) -> Hl {
    match ft {
        FileType::Rust => {
            match word {
                "as"|"async"|"await"|"const"|"crate"|"dyn"|"enum"|"extern"|"fn"|"impl"|"let"|"mod"|"move"|"mut"|"pub"|"ref"|"static"|"struct"|"super"|"trait"|"type"|"union"|"unsafe"|"use"|"where"|"Self" => Hl::Keyword1,
                "break"|"continue"|"else"|"for"|"if"|"in"|"loop"|"match"|"return"|"while" => Hl::Keyword2,
                "Box"|"Err"|"None"|"Ok"|"Option"|"Result"|"Some"|"String"|"Vec"|"bool"|"char"|"f32"|"f64"|"i128"|"i16"|"i32"|"i64"|"i8"|"isize"|"u128"|"u16"|"u32"|"u64"|"u8"|"usize" => Hl::Type,
                "true"|"false" => Hl::Number,
                "self" => Hl::SelfKw,
                _ => Hl::Normal,
            }
        }
        FileType::C => {
            match word {
                "auto"|"const"|"enum"|"extern"|"inline"|"register"|"restrict"|"sizeof"|"static"|"struct"|"typedef"|"union"|"volatile" => Hl::Keyword1,
                "break"|"case"|"continue"|"default"|"do"|"else"|"for"|"goto"|"if"|"return"|"switch"|"while" => Hl::Keyword2,
                "char"|"double"|"float"|"int"|"long"|"short"|"signed"|"unsigned"|"void" => Hl::Type,
                _ => Hl::Normal,
