// Highlighting for a single line, given filetype and multiline states
// Returns Vec<Hl> per char (same len as chars), plus updated states for next line
// States: in_block_comment (bool), in_string (Option<char> for ", ', `? Actually for " spanning, ' spanning (py/js), ` spanning (go))
// For " spanning: in_double_string bool? For ' spanning (py/js): in_single_string? For ` (go): in_backtick?
// For char literals (', 3-4 chars) in rust/c/cpp/go: not multiline, handled per line, no state.
// For block comments /* */: in_block bool, spanning.
// For line comments //, #: per line, no state (to end of line).

#[derive(Clone, Copy, PartialEq, Eq)]
struct HlState {
    in_block: bool,
    in_double: bool, // " spanning (all non-plain? Actually for plain, no strings. For rust/c/cpp/go/py/js, " spanning)
    in_single: bool, // ' spanning (only py/js, where ' is string, not char)
    in_backtick: bool, // ` spanning (only go)
}

impl HlState {
    fn new() -> Self { HlState { in_block: false, in_double: false, in_single: false, in_backtick: false } }
}

// Check if ft has block comments /* */
fn has_block(ft: FileType) -> bool {
    matches!(ft, FileType::Rust|FileType::C|FileType::Cpp|FileType::Javascript|FileType::Go)
}
fn line_comment_start(ft: FileType) -> Option<&'static str> {
    match ft {
        FileType::Rust|FileType::C|FileType::Cpp|FileType::Javascript|FileType::Go => Some("//"),
        FileType::Python => Some("#"),
        FileType::Plain => None,
    }
}

// Highlight line: chars is Vec<char> of line content (without \n)
// Returns (hl_per_char, next_state)
fn highlight_line(chars: &[char], ft: FileType, mut state: HlState) -> (Vec<Hl>, HlState) {
    let n = chars.len();
    let mut hl = vec![Hl::Normal; n];
    if ft == FileType::Plain {
        return (hl, state);
    }
    let mut i = 0;
    // If in_block at start, whole line starts as comment until */?
    // Similarly in_double/in_single/in_backtick at start: whole line starts as string until closing?
    // We need to handle these states first.
    // For simplicity, iterate i from 0, handling states.

    // Track def chain: after_def flag for 214 chain
    let mut after_def = false;
    // To implement def chain correctly, we need to know word boundaries and punctuation.
    // We'll process line left-to-right, handling strings/comments/numbers/keywords, and updating after_def.
    // after_def is set to true when we encounter a def trigger word.
    // For each subsequent word/punct, update as per rules.

    // Helper to check if chars[i..] starts with prefix
