fn parse_csi(params: &str, final_c: char) -> Key {
    match final_c {
        'A' => {
            // Up: check params for Ctrl (1;5) => PrevPara, else Up (including Alt 1;3, Shift 1;2, etc. treated as plain Up)
            if params == "1;5" {
                Key::PrevPara // Ctrl-Up
            } else {
                Key::Up
            }
        }
        'B' => {
            if params == "1;5" {
                Key::NextPara // Ctrl-Down
            } else {
                Key::Down
            }
        }
        'C' => {
            if params == "1;5" {
                Key::NextWord // Ctrl-Right
            } else {
                Key::Right
            }
        }
        'D' => {
            if params == "1;5" {
                Key::PrevWord // Ctrl-Left
            } else {
                Key::Left
            }
        }
        'H' => {
            // Home: params "", "1", "7", "1;2", "1;3", etc. treated as Home, except "1;5" (Ctrl-Home) unmapped C-HOME
            if params == "1;5" {
                Key::Unmapped("C-HOME".to_string())
            } else {
                Key::Head
            }
        }
        'F' => {
            if params == "1;5" {
                Key::Unmapped("C-END".to_string())
            } else {
                Key::End
            }
        }
        '~' => {
            // Special keys: params "1","7" => Home, "4","8" => End, "3" => Delete, "5" => PageUp, "6" => PageDown, others (11,12,13,14,15,17,18,19,20,21,23,24, etc.) ignored
            // For params with modifiers like "3;5" (Ctrl-Delete), treat as plain Delete (ignore modifier)? As observed, Ctrl-Delete treated as Delete. Good: for "~", look at first number before ";"? E.g., "3;5" => 3 => Delete. "5;5"? Probably PageUp? Let's implement: split at ';', take first part.
            let first = params.split(';').next().unwrap_or("");
            // Also handle params like "1;5" for Home/End with ~? Actually Home/End with ~ are "1~","4~","7~","8~", not "H/F". Modified Home/End with ~? Unlikely, but handle similarly: first part determines.
            match first {
                "1"|"7" => Key::Head,
                "4"|"8" => Key::End,
                "3" => Key::DeleteNext,
                "5" => Key::PrevPage,
                "6" => Key::NextPage,
                _ => Key::Ignored,
            }
        }
        'Z' => {
            // Shift-Tab (CSI Z, params "" or "1;2"? Actually Shift-Tab is ESC [ Z (no params). Ignored.
            Key::Ignored
        }
        _ => Key::Ignored,
    }
}
