// Additional Editor methods for prompts, search, save/open, main loop helpers

impl Editor {
    fn update_filetype_current(&mut self) {
        let buf = self.current_buffer_mut();
        if let Some(ref f) = buf.filename {
            buf.filetype = detect_filetype(f);
        } else {
            buf.filetype = FileType::Plain;
        }
    }

    // Find all search matches for query in current buffer (non-overlapping, left-to-right, per line)
    // Returns Vec<(cy, cx_start_char_idx, len_chars)> in file order (line-major)
    fn find_matches(&self, query: &str) -> Vec<(usize, usize, usize)> {
        if query.is_empty() {
            return Vec::new();
        }
        let buf = self.current_buffer();
        let qchars: Vec<char> = query.chars().collect();
        let qlen = qchars.len();
        let mut res = Vec::new();
        for (cy, line) in buf.lines.iter().enumerate() {
            let chars: Vec<char> = line.chars().collect();
            if chars.len() < qlen { continue; }
            let mut i = 0;
            while i + qlen <= chars.len() {
                if chars[i..i+qlen] == qchars[..] {
                    res.push((cy, i, qlen));
                    i += qlen; // non-overlapping, skip past match (as observed: "aaa" with "aa" matches only at 0, not at 1 (overlapping), since i+=qlen=2, next i=2, chars[2..4]? len=3, 2+2=4>3, stop. Good: only one match. For "aaaa" with "aa", matches at 0 and 2 (i=0 match, i=2 match, i=4 stop). Good.
                } else {
                    i += 1;
                }
            }
        }
        res
    }
}

